import sys
from functools import wraps

def count_calls(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return func(*args, **kwargs)
    wrapper.calls = 0
    return wrapper

@count_calls
def greet():
    return "hi"

n = int(sys.stdin.read().strip())
for _ in range(n):
    greet()
print(greet.calls)

import sys

class Vector:
    def __init__(self, x, y):
        self.x, self.y = x, y

    def __add__(self, other):
        return Vector(self.x + other.x, self.y + other.y)

    def __repr__(self):
        return f"Vector({self.x}, {self.y})"

lines = sys.stdin.read().splitlines()
a = Vector(*map(int, lines[0].split()))
b = Vector(*map(int, lines[1].split()))
print(a + b)

import sys

class Temperature:
    def __init__(self, celsius):
        self.celsius = celsius

    @property
    def fahrenheit(self):
        return self.celsius * 9 // 5 + 32

t = Temperature(int(sys.stdin.read().strip()))
print(t.fahrenheit)

import sys
from abc import ABC, abstractmethod

PI = 3.14159

class Shape(ABC):
    @abstractmethod
    def area(self):
        ...

class Rect(Shape):
    def __init__(self, w, h):
        self.w, self.h = w, h

    def area(self):
        return self.w * self.h

class Circle(Shape):
    def __init__(self, r):
        self.r = r

    def area(self):
        return PI * self.r * self.r

lines = sys.stdin.read().splitlines()
n = int(lines[0])
for i in range(1, n + 1):
    parts = lines[i].split()
    if parts[0] == "rect":
        shape = Rect(int(parts[1]), int(parts[2]))
    else:
        shape = Circle(int(parts[1]))
    print(f"{shape.area():.2f}")

import sys

class Observer:
    def __init__(self, name):
        self.name = name

    def update(self, message):
        print(f"{self.name}: {message}")

class Subject:
    def __init__(self):
        self._observers = []

    def attach(self, observer):
        self._observers.append(observer)

    def notify(self, message):
        for observer in self._observers:
            observer.update(message)

lines = sys.stdin.read().splitlines()
n = int(lines[0])
subject = Subject()
for i in range(1, n + 1):
    subject.attach(Observer(f"observer{i}"))
subject.notify(lines[1])
